-- ===== Part 2: row-level security =====
ALTER TABLE report_schedules ENABLE ROW LEVEL SECURITY;
ALTER TABLE report_schedules FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON report_schedules
  USING (organization_id = pcp_current_org()) WITH CHECK (organization_id = pcp_current_org());

ALTER TABLE generated_reports ENABLE ROW LEVEL SECURITY;
ALTER TABLE generated_reports FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON generated_reports
  USING (organization_id = pcp_current_org()) WITH CHECK (organization_id = pcp_current_org());

ALTER TABLE report_deliveries ENABLE ROW LEVEL SECURITY;
ALTER TABLE report_deliveries FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON report_deliveries
  USING (organization_id = pcp_current_org()) WITH CHECK (organization_id = pcp_current_org());

-- ===== Part 3: scheduler functions (BR-15-07: no BYPASSRLS) and tenant guard resolver =====
CREATE FUNCTION pcp_due_report_schedules(p_now timestamptz)
  RETURNS TABLE (organization_id uuid, id uuid, next_run_at timestamptz)
  LANGUAGE sql STABLE SECURITY DEFINER
  SET search_path = public, pg_temp
  AS $$
    SELECT s.organization_id, s.id, s.next_run_at FROM report_schedules s
    WHERE s.enabled AND s.next_run_at <= p_now
    ORDER BY s.next_run_at
    LIMIT 500
  $$;

-- Compare-and-set: only the dispatcher that saw p_expected moves the schedule on.
CREATE FUNCTION pcp_advance_report_schedule(p_id uuid, p_expected timestamptz, p_next timestamptz)
  RETURNS boolean
  LANGUAGE sql VOLATILE SECURITY DEFINER
  SET search_path = public, pg_temp
  AS $$
    WITH moved AS (
      UPDATE report_schedules SET next_run_at = p_next
      WHERE id = p_id AND next_run_at = p_expected
      RETURNING 1
    )
    SELECT EXISTS (SELECT 1 FROM moved)
  $$;

CREATE FUNCTION pcp_resolve_report_object(p_kind text, p_id uuid, p_user uuid)
  RETURNS TABLE (organization_id uuid, product_id uuid)
  LANGUAGE sql STABLE SECURITY DEFINER
  SET search_path = public, pg_temp
  AS $$
    SELECT s.organization_id, s.product_id FROM report_schedules s
    JOIN organization_members m ON m.organization_id = s.organization_id AND m.user_id = p_user
    WHERE p_kind = 'report_schedule' AND s.id = p_id
    UNION ALL
    SELECT r.organization_id, r.product_id FROM generated_reports r
    JOIN organization_members m ON m.organization_id = r.organization_id AND m.user_id = p_user
    WHERE p_kind = 'report' AND r.id = p_id
  $$;

ALTER FUNCTION pcp_due_report_schedules(timestamptz) OWNER TO pcp_rls_definer;
REVOKE ALL ON FUNCTION pcp_due_report_schedules(timestamptz) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION pcp_due_report_schedules(timestamptz) TO pcp_scheduler;

-- The definer role reads everything but may only move next_run_at.
GRANT UPDATE (next_run_at) ON report_schedules TO pcp_rls_definer;
ALTER FUNCTION pcp_advance_report_schedule(uuid, timestamptz, timestamptz) OWNER TO pcp_rls_definer;
REVOKE ALL ON FUNCTION pcp_advance_report_schedule(uuid, timestamptz, timestamptz) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION pcp_advance_report_schedule(uuid, timestamptz, timestamptz) TO pcp_scheduler;

ALTER FUNCTION pcp_resolve_report_object(text, uuid, uuid) OWNER TO pcp_rls_definer;
REVOKE ALL ON FUNCTION pcp_resolve_report_object(text, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION pcp_resolve_report_object(text, uuid, uuid) TO pcp_app;
